type rate struct { from time.Time; cents int64 }     // sorted by from, oldest first

func (h []rate) at(when time.Time) (int64, bool) {
    i, _ := slices.BinarySearchFunc(h, when, func(r rate, t time.Time) int {
        if !r.from.After(t) { return -1 }             // r.from <= t: keep searching right
        return 1
    })
    if i == 0 { return 0, false }                     // no version in force on `when`
    return h[i-1].cents, true                         // latest milestone <= `when`
}
